CREATE TABLE IF NOT EXISTS nguoi_dung(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, name varchar(180) NOT NULL, email varchar(180) UNIQUE NOT NULL, password varchar(100) NOT NULL, role varchar(10) NOT NULL CHECK(role IN ('ADMIN','KHO','DP')), active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS khach_hang(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, name varchar(180) NOT NULL, phone varchar(30), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS dia_diem_giao(id bigserial PRIMARY KEY, customer_id bigint NOT NULL REFERENCES khach_hang, code varchar(60) UNIQUE NOT NULL, name varchar(180) NOT NULL, address text NOT NULL, region varchar(2) NOT NULL CHECK(region IN ('MB','MT','MN')), latitude numeric(10,7), longitude numeric(10,7), active boolean NOT NULL DEFAULT true, CHECK(latitude BETWEEN -90 AND 90), CHECK(longitude BETWEEN -180 AND 180));
CREATE TABLE IF NOT EXISTS don_hang(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, customer_id bigint NOT NULL REFERENCES khach_hang, created_by bigint NOT NULL REFERENCES nguoi_dung, status varchar(30) NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now(), note text);
CREATE TABLE IF NOT EXISTS yeu_cau_giao(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, order_id bigint NOT NULL REFERENCES don_hang, location_id bigint NOT NULL REFERENCES dia_diem_giao, earliest date NOT NULL, latest date NOT NULL, early_consent text, status varchar(30) NOT NULL DEFAULT 'OPEN', CHECK(latest>=earliest));
CREATE TABLE IF NOT EXISTS linh_kien(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, name varchar(180) NOT NULL, unit varchar(30) NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS chi_tiet_yeu_cau(id bigserial PRIMARY KEY, requirement_id bigint NOT NULL REFERENCES yeu_cau_giao, part_id bigint NOT NULL REFERENCES linh_kien, quantity integer NOT NULL CHECK(quantity>0), UNIQUE(requirement_id,part_id));
CREATE TABLE IF NOT EXISTS nha_cung_cap(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, name varchar(180) NOT NULL, phone varchar(30), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS xac_nhan_cung_cap(id bigserial PRIMARY KEY, supplier_id bigint NOT NULL REFERENCES nha_cung_cap, detail_id bigint NOT NULL REFERENCES chi_tiet_yeu_cau, quantity integer NOT NULL CHECK(quantity>0), promised_date date NOT NULL, status varchar(20) NOT NULL CHECK(status IN ('ACCEPTED','REJECTED')), note text, created_by bigint NOT NULL REFERENCES nguoi_dung, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS xe(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, plate varchar(30) UNIQUE NOT NULL, region varchar(2) CHECK(region IN ('MB','MT','MN')), capacity_kg numeric(12,3) NOT NULL CHECK(capacity_kg>0 AND capacity_kg<=18000), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS chuyen_nhap(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, vehicle_id bigint NOT NULL REFERENCES xe, planned_at timestamptz NOT NULL, status varchar(30) NOT NULL DEFAULT 'EXPECTED', created_by bigint NOT NULL REFERENCES nguoi_dung, unloaded_at timestamptz, note text);
CREATE TABLE IF NOT EXISTS lo_nhap(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, inbound_id bigint NOT NULL REFERENCES chuyen_nhap, supplier_id bigint NOT NULL REFERENCES nha_cung_cap);
CREATE TABLE IF NOT EXISTS khu_cho(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, name varchar(180) NOT NULL, region varchar(2) NOT NULL CHECK(region IN ('MB','MT','MN')), capacity integer NOT NULL CHECK(capacity>0), active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS thung_hang(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, source_code varchar(100) NOT NULL, lot_id bigint NOT NULL REFERENCES lo_nhap, part_id bigint NOT NULL REFERENCES linh_kien, detail_id bigint NOT NULL REFERENCES chi_tiet_yeu_cau, supply_id bigint NOT NULL REFERENCES xac_nhan_cung_cap, expected_qty integer NOT NULL CHECK(expected_qty>0), quantity integer CHECK(quantity>0), gross_kg numeric(12,3) NOT NULL CHECK(gross_kg>0 AND gross_kg<=18000), status varchar(30) NOT NULL DEFAULT 'EXPECTED', staging_id bigint REFERENCES khu_cho, inspected_by bigint REFERENCES nguoi_dung, inspected_at timestamptz, staged_at timestamptz, note text, UNIQUE(lot_id,source_code));
CREATE TABLE IF NOT EXISTS cong_kho(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL CHECK(code IN ('IN01','IN02','IN03','OUT01','OUT02','OUT03')), name varchar(180) NOT NULL, kind varchar(3) NOT NULL CHECK(kind IN ('IN','OUT')), active boolean NOT NULL DEFAULT true, CHECK((kind='IN' AND code LIKE 'IN%') OR (kind='OUT' AND code LIKE 'OUT%')));
CREATE TABLE IF NOT EXISTS chuyen_xuat(id bigserial PRIMARY KEY, code varchar(60) UNIQUE NOT NULL, vehicle_id bigint NOT NULL REFERENCES xe, region varchar(2) NOT NULL CHECK(region IN ('MB','MT','MN')), driver varchar(180) NOT NULL, planned_at timestamptz NOT NULL, status varchar(30) NOT NULL DEFAULT 'DRAFT', created_by bigint NOT NULL REFERENCES nguoi_dung, dispatched_at timestamptz, dispatched_by bigint REFERENCES nguoi_dung, underload_reason text, note text);
CREATE TABLE IF NOT EXISTS luot_phuc_vu(id bigserial PRIMARY KEY, gate_id bigint NOT NULL REFERENCES cong_kho, inbound_id bigint REFERENCES chuyen_nhap, outbound_id bigint REFERENCES chuyen_xuat, planned_start timestamptz NOT NULL, planned_end timestamptz NOT NULL, arrived_at timestamptz, left_at timestamptz, status varchar(20) NOT NULL DEFAULT 'WAITING', created_by bigint NOT NULL REFERENCES nguoi_dung, CHECK((inbound_id IS NULL)<>(outbound_id IS NULL)), CHECK(planned_end>planned_start));
CREATE TABLE IF NOT EXISTS diem_giao_chuyen(id bigserial PRIMARY KEY, trip_id bigint NOT NULL REFERENCES chuyen_xuat, location_id bigint NOT NULL REFERENCES dia_diem_giao, sequence_no integer NOT NULL CHECK(sequence_no>0), address_snapshot text NOT NULL, status varchar(30) NOT NULL DEFAULT 'PENDING', UNIQUE(trip_id,location_id), UNIQUE(trip_id,sequence_no));
CREATE TABLE IF NOT EXISTS phan_bo_thung(id bigserial PRIMARY KEY, box_id bigint NOT NULL REFERENCES thung_hang, stop_id bigint NOT NULL REFERENCES diem_giao_chuyen, status varchar(30) NOT NULL DEFAULT 'ALLOCATED', allocated_by bigint NOT NULL REFERENCES nguoi_dung, allocated_at timestamptz NOT NULL DEFAULT now(), loaded_by bigint REFERENCES nguoi_dung, loaded_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_allocation ON phan_bo_thung(box_id) WHERE status IN ('ALLOCATED','LOADED','SHIPPED','RETURN_PENDING');
CREATE UNIQUE INDEX IF NOT EXISTS one_gate_occupied ON luot_phuc_vu(gate_id) WHERE status='IN_GATE';
CREATE TABLE IF NOT EXISTS ket_qua_giao_hang(id bigserial PRIMARY KEY, stop_id bigint NOT NULL REFERENCES diem_giao_chuyen, delivered_at timestamptz NOT NULL, recorded_by bigint NOT NULL REFERENCES nguoi_dung, note text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS chi_tiet_giao(id bigserial PRIMARY KEY, result_id bigint NOT NULL REFERENCES ket_qua_giao_hang, allocation_id bigint NOT NULL REFERENCES phan_bo_thung, status varchar(20) NOT NULL CHECK(status IN ('DELIVERED','FAILED','RETURN_PENDING')), late boolean NOT NULL DEFAULT false, note text, UNIQUE(result_id,allocation_id));
CREATE INDEX IF NOT EXISTS box_detail ON thung_hang(detail_id);
CREATE INDEX IF NOT EXISTS allocation_stop ON phan_bo_thung(stop_id);
CREATE INDEX IF NOT EXISTS requirement_order ON yeu_cau_giao(order_id);
